 a=v['D1'];K=a['complete_kernel'];r=a['rank'];n=30-r
 I=a['minor_rows'];J=a['minor_columns'];free=[j for j in range(30)if j not in J]
 assert rec['source_matrix_path']==matrixpath and rec['original_parameterization_chain']==[dict(m)for m in chain]
