 assert matrix is not None and len(matrix)==350 and all(len(row)==30 for row in matrix)
 assert scalar(a['minor_determinant'])
 parsedK=[[scalar(s)for s in row]for row in K]
 assert all(parsedK[i][j]==H.R3(int(k==j))for k,i in enumerate(free)for j in range(n))
 assert all(not q for row in parsedK[27:30]for q in row)
 at=tuple(chain)+((('tau',v['parameter']),),)if 'parameter'in v else tuple(chain)
 # Matrix rows are read from their original ancestor and every saved mapping
 # is composed simultaneously before each final rational-root specialization.
 for i in I:
  row=[value(str(s),at)for s in matrix[i]]
  for j in range(n):
   total=H.R3(0)
   for k,c in enumerate(row):
    if c and parsedK[k][j]:total=total+c*parsedK[k][j]
   assert not total,(rec['path'],i,j)
   products+=1
 checked.append({'path':rec['path'],'selected_rank':r,'nullity':n,'original_parameterization_chain':[dict(m)for m in chain],'root_parameter':v.get('parameter'),'free_identity':True,'selected_rows_times_K_zero':True,'all_C_rows_zero':True})
